@@ -0,0 +1,48 @@
+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`; the ingredients are consumed with ref `sale:<ticket>`.
+// A ticket is recorded once: tickets already in the store are skipped.
+// Recording is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a sale with this ticket has been recorded. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Records sale lines { row, ticket, soldAt, dishId, qty }, skipping known tickets; returns { tickets, dishes }. */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = getDish(store, l.dishId);
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    return { line: l, uses };
+  });
+  // Check stock for the whole file first, so nothing is taken when any row runs out.
+  const left = new Map();
+  for (const { line, uses } of planned) {
+    for (const u of uses) {
+      if (!left.has(u.itemId)) left.set(u.itemId, round3(onHand(store, u.itemId)));
+      const available = left.get(u.itemId);
+      if (available < u.qty) {
+        const item = getItem(store, u.itemId);
+        throw new AppError("sale_out_of_stock", { row: line.row, item: item.name, available, unit: item.unit });
+      }
+      left.set(u.itemId, round3(available - u.qty));
+    }
+  }
+  store.data.sales ??= [];
+  for (const { line, uses } of planned) {
+    for (const u of uses) consume(store, u.itemId, u.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty, uses });
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
